import re, os, sys, subprocess

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s01"

sites = []
with open(sys.argv[1]) as f:
    for line in f:
        line = line.rstrip("\n")
        m = re.match(r'([^:]+):(\d+):(.*)', line)
        if m:
            sites.append((m.group(1), int(m.group(2))))

# group by file
from collections import defaultdict
byfile = defaultdict(list)
for path, ln in sites:
    byfile[path].append(ln)

# patterns that produce a pointer into skb data
DERIVE = re.compile(
    r'=\s*(?:\(?\s*[A-Za-z_][\w]*\s*\*\s*\)?\s*)?'      # optional cast start (loose)
    r'(skb_header_pointer\s*\(|'
    r'skb_network_header\s*\(|'
    r'skb_transport_header\s*\(|'
    r'skb_mac_header\s*\(|'
    r'skb_->data|'
    r'skb->data|'
    r'\w+->data\s*\+|'
    r'skb->head|'
    r'skb_inner_network_header\s*\(|'
    r'skb_inner_transport_header\s*\(|'
    r'skb_reset|'
    r'skb_set_network_header|'
    r'skb_set_transport_header)'
)
# capture variable name from "TYPE *name =" or "name ="
VARDECL = re.compile(r'(?:^|[^>\w.])([A-Za-z_]\w*)\s*(?:\[[^\]]*\])?\s*=\s*')

PULLCALL = re.compile(r'\b(pskb_may_pull|pskb_may_pull_reason|__pskb_pull_tail|pskb_pull|pskb_pull_tail)\s*\(')

def func_ranges(lines):
    """Yield (start, end) 0-based line index ranges of top-level functions."""
    starts = []
    for i, l in enumerate(lines):
        if re.match(r'^(static\s+)?(inline\s+)?(const\s+)?[A-Za-z_][\w\s\*,\(\)\[\]]*\(.*\)\s*$', l) and not l.startswith('#'):
            # candidate signature line; next non-empty line should be '{'
            j = i + 1
            while j < len(lines) and lines[j].strip() == '':
                j += 1
            if j < len(lines) and lines[j].startswith('{'):
                starts.append((i, j))
    # function body ends at a '}' at column 0
    funcs = []
    for i, (sig, brace) in enumerate(starts):
        end = len(lines)
        for k in range(brace, len(lines)):
            if lines[k].startswith('}'):
                end = k
                break
        else:
            end = len(lines)
        funcs.append((sig, brace, end))
    return funcs

results = []
for path, lns in sorted(byfile.items()):
    full = os.path.join(ROOT, path)
    try:
        with open(full, errors='replace') as f:
            lines = f.readlines()
    except OSError:
        continue
    for (sig, brace, end) in func_ranges(lines):
        body = lines[brace:end+1]
        pull_lines = []
        for idx in range(brace, end+1):
            if idx+1 in lns and PULLCALL.search(lines[idx]):
                pull_lines.append(idx)
        if not pull_lines:
            continue
        # find derived-pointer assignments
        assigns = []  # (idx, var)
        for idx in range(brace, end+1):
            l = lines[idx]
            if PULLCALL.search(l):
                continue
            if DERIVE.search(l):
                m = VARDECL.search(l)
                if m:
                    assigns.append((idx, m.group(1), l.strip()))
        # find uses of those vars after the first pull
        for (aidx, var, atext) in assigns:
            for pidx in pull_lines:
                if pidx > aidx:
                    # search for var use after pull within function
                    used = []
                    for uidx in range(pidx+1, end+1):
                        ul = lines[uidx]
                        if re.search(r'[^>\w.]' + re.escape(var) + r'(?![\w])', ul):
                            used.append((uidx+1, ul.strip()))
                    if used:
                        results.append((path, aidx+1, atext, var, pidx+1, lines[pidx].strip(), used[:6]))
                    break

for r in results:
    print("### %s" % r[0])
    print("  SAVE line %d: %s" % (r[1], r[2]))
    print("  VAR: %s" % r[3])
    print("  PULL line %d: %s" % (r[4], r[5]))
    for u in r[6]:
        print("  USE  line %d: %s" % u)
    print()
