DECL = re.compile(r"^\s*(?:static\s+|const\s+|volatile\s+)*(?:struct\s+|enum\s+|union\s+)?[\w\d_]+(?:\s+|\s*\*\s*|\s+\*|\*\*|\s*\*)([\w\d_]+)\s*=\s*(.+?);\s*$")
CASTDECL = re.compile(r"^\s*(?:const\s+)?(?:struct\s+)?[\w\d_]+(?:\s*\*+\s*|\s+)([\w\d_]+)\s*=\s*(.+?);\s*$")

BASE_DERIVE = re.compile(
    r"(->data\b|skb_header_pointer\s*\(|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|skb_copy_bits\s*\()"
)

results = []
files = []
for dirpath, dirnames, filenames in os.walk(ROOT):
    d = dirpath.replace(ROOT, "")
    if not (d.startswith("/net") or d.startswith("/drivers")):
        continue
    for fn in filenames:
        if fn.endswith(".c"):
            files.append(os.path.join(dirpath, fn))
print(f"# files: {len(files)}", file=sys.stderr)

for path in files:
    try:
        funcs, lines = extract_functions(path)
    except Exception:
        continue
    for (fs, fe) in funcs:
        if fe - fs > 600:
            continue
        body = lines[fs:fe+1]
        if not PULL.search("\n".join(body)):
            continue
        pull_lines = [k for k, l in enumerate(body) if PULL.search(l)]
        # collect assignments building derived pointers: map var -> list of (line, is_base)
        assigns = {}   # var -> list of (k, expr, base)
        order = []
        for k, l in enumerate(body):
            m = CASTDECL.match(l)
            var = expr = None
            if m and ("*" in l.split("=")[0]):
                var, expr = m.group(1), m.group(2)
            else:
                m2 = ASSIGN.match(l)
                if m2:
                    var, expr = m2.group(1), m2.group(2)
            if var is None:
                continue
            if expr is None:
                continue
            base = bool(BASE_DERIVE.search(expr))
            derived_from_tracked = any(re.search(r"\b"+re.escape(v)+r"\b", expr) for v in assigns)
            if base or derived_from_tracked:
                assigns.setdefault(var, []).append((k, expr, base))
                order.append(var)
        if not assigns:
            continue
        for var, alist in assigns.items():
            for (k, expr, base) in alist:
                # find next pull after save
                next_pulls = [p for p in pull_lines if p > k]
                if not next_pulls:
                    continue
                # refetch check: any reassignment of var between save and first next pull?
                p0 = next_pulls[0]
                refetched = False
                for j in range(k+1, p0):
                    if re.match(r"^\s*" + re.escape(var) + r"\s*=[^=]", body[j]):
                        refetched = True
                if refetched:
                    continue
                # use after the pull (until reassignment or function end)
                for j in range(p0+1, len(body)):
                    l = body[j]
                    if re.match(r"^\s*" + re.escape(var) + r"\s*=[^=]", l):
                        break  # reassignment before use
                    if re.search(r"\b" + re.escape(var) + r"\b", l):
                        results.append((path, fs+k+1, fs+p0+1, fs+j+1, var, body[k].strip()[:110], l.strip()[:110]))
                        break
print(f"# hits: {len(results)}", file=sys.stderr)
for r in results:
    print("\t".join(str(x) for x in r))
EOF
